/**
 * Inert replacement for the WebAssembly bridge (src/wasm/wasmBridge.ts).
 *
 * The real bridge imports a package generated by wasm-pack, which is not part
 * of the repository. Tests exercise the TypeScript layer only, so every
 * bridge function is replaced by one that does nothing.
 */

type WasmBridgeModule = typeof import('../../wasm/wasmBridge');
type WasmBridgeExportName = keyof WasmBridgeModule;

/** Result returned by the stubbed command execution: never successful. */
export interface WasmCommandResultStub {
  readonly success: false;
  readonly output: string;
}

/**
 * Builds a fresh stub. The `satisfies` clause ties the stub to the real
 * module: a missing or an extra export name fails the test type check.
 */
export function createWasmBridgeStub() {
  return {
    initWasm: async (): Promise<void> => undefined,
    wasmSetTopology: (): void => undefined,
    wasmGetDevices: (): unknown[] => [],
    // Reporting "not handled" lets callers fall back to the TypeScript CLI.
    wasmExecuteCommand: (): WasmCommandResultStub => ({ success: false, output: '' }),
    wasmPing: (): string => ''
  } satisfies Record<WasmBridgeExportName, (...args: never[]) => unknown>;
}
